@pytest.mark.uninitialized
@test_timeout(local=5 * 60, batch=5 * 60)
@pytest.mark.parametrize('requester_pays', ['hail-vdc', ('hail-vdc', ['hail-test-requester-pays-fds32']), ('hail-vdc', ['hail-test-requester-pays-fds32', 'other-bucket'])])
def test_requester_pays_with_project_more_than_one_partition(requester_pays):
    expected_file_contents = [hl.Struct(f0='idx'), hl.Struct(f0='0'), hl.Struct(f0='1'), hl.Struct(f0='2'), hl.Struct(f0='3'), hl.Struct(f0='4'), hl.Struct(f0='5'), hl.Struct(f0='6'), hl.Struct(f0='7'), hl.Struct(f0='8'), hl.Struct(f0='9')]
    hl_init_for_test(gcs_requester_pays_configuration=requester_pays)
    assert hl.import_table('gs://hail-test-requester-pays-fds32/zero-to-nine', no_header=True, min_partitions=8).collect() == expected_file_contents

